raw:
{
  "spells": [
    {
      "id": "spell_fire_10",
      "theory": "炉膛鼓焰将魔力灌入已燃的炭块或柴堆内部，使火焰在原有燃料上短暂升温。它不凭空生火，只催促现有火舌更旺，因此炉膛里必须有足够的炭柴。升高的温度集中在火焰附近，铁砧和陶罐会被更快烧透，但离开炉膛的热气仍会迅速消散。",
      "casting": "手掌朝炉膛张开，以拇指在掌心画一个向下的短弧，同时缓缓吐气。待火舌从橙转白时收拢五指，表示停止加温。",
      "failure": "火焰突然蹿高又缩回，留下大量黑烟和未烧透的炭块。若施法时掌心弧线画反，热气会倒卷出炉口，燎焦近处草料或衣物。",
      "counters": [
        "往炉膛口盖一块湿麻布，隔断施法者与火焰的接触。",
        "抽出部分柴炭降低燃料密度，使升温失去依托。"
      ],
      "socialConsequences": "铁匠和陶匠在赶工时愿意请人鼓焰，但会先讲好燃料由谁添补。柴炭商贩担心升温加快耗料，常要求按实际消耗结账。炉膛属于作坊主时，外人动手前须经主人点头，否则会被视作插手别人的生计。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "consent"
      },
      "proficiencyEffects": [
        "初学时升温忽高忽低，铁料容易受热不均。",
        "熟练后能稳住火舌，让炭块烧得更匀。",
        "老手可把升温限制在炉膛中心，减少外溢热浪。",
        "更高明者仍只催旺现有炉火，不额外生热。"
      ]
    },
    {
      "id": "spell_fire_11",
      "theory": "隔焰罩在受术者皮肤外结出一层薄薄的魔力膜，这层膜会吸收并分散接触到的外来火焰。它只对火起作用，刀剑和钝击照样穿透。膜依附在活人身上，受术者剧烈翻滚或跳入水中会提前削弱它，但不会反过来伤害本人。",
      "casting": "并拢两指从受术者肩头划到手腕，再在胸前点一个短横。指尖离开时若感到轻微回弹，说明膜已贴合。",
      "failure": "膜面出现裂纹，热浪仍会透进来，只在皮肤上留下灼痛红斑。若划动过快，罩子可能只盖住半边身子，另一侧衣角照样被火舌舔燃。",
      "counters": [
        "往受术者身上泼大量冷水，水膜会顶开魔力层。",
        "用长杆把受术者推离火源，膜离火后不久便自行消散。"
      ],
      "socialConsequences": "救火队和厨房帮工乐于让人临时加罩，但会追问魔力能撑多久，好安排轮换。皮匠担心罩子让人误以为可以徒手抓火，事后多出烫伤生意。若在别人宅院里施放，主人常要求先说明只护人、不挡自家炉火。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "consent"
      },
      "proficiencyEffects": [
        "初学时隔焰罩边缘易翘，护不住手腕和脖颈。",
        "熟练后能覆盖全身，灼痛感明显减轻。",
        "老手可把膜贴在衣外，减少对动作的妨碍。",
        "更高明者仍只削火伤，不挡刀剑与坠石。"
      ]
    },
    {
      "id": "spell_fire_12",
      "theory": "熔缝术把魔力聚在铁料与金属裂缝的接缝处，使两者表面短暂软化并咬合。它不能凭空生出铁，也不能补上缺掉的整块部件，只把带来的铁料填进已有裂口。冷却后接缝留下颜色略深的线，受力时仍可能从旁边重新开裂。",
      "casting": "左手按住铁料，右手食指沿裂缝来回划三次，每次划动时轻轻送入魔力。感到铁料微微发软后，用拇指压实接缝。",
      "failure": "铁料没有软到位，接缝处鼓起小泡，冷却后一敲就碎。若魔力送得太急，裂缝反而向两侧延长，把原本能补的破口撕得更大。",
      "counters": [
        "待接缝完全冷却后，用冷水浇淋使其收缩开裂。",
        "用锤子从侧面敲击接缝，未咬合的铁料会整片脱落。"
      ],
      "socialConsequences": "铁匠和修车匠会请人补锅补轴，但坚持要亲眼看着冷却，免得留下暗伤。卖新铁件的商人担心旧货被反复修补，压低自家销路，常提醒买主修补件不耐重载。若给别人的工具补缝，须先说明只填现有裂缝，不包以后不断。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时铁料软硬不匀，接缝里常留气孔。",
        "熟练后能沿裂缝均匀填料，冷却较少变形。",
        "老手可控制软化范围，不伤裂缝旁边的铁面。",
        "更高明者仍不能造出缺失部件，只补已有裂口。"
      ]
    }
  ]
}
